-- Recreates the 3 empty stub tables that existed in project pedjksnjyltbkjhstaqp before SLI_TECH migration 000.
-- (Run 001_core_ROLLBACK.sql etc. first if the real schema was applied afterwards.)
create table public.smg_services (
  id bigint generated by default as identity primary key, provider_service_id text not null unique, platform text not null, name text not null,
  source_rate numeric not null check (source_rate >= 0), source_currency text not null default 'INR', price_ngn_per_1000 numeric not null check (price_ngn_per_1000 >= 0),
  min_quantity integer not null default 1 check (min_quantity > 0), max_quantity integer not null default 1000000, provider_verified boolean not null default false,
  is_active boolean not null default false, synced_at timestamptz, created_at timestamptz not null default now(), check (max_quantity >= min_quantity));
create table public.smg_orders (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, service_id bigint not null references public.smg_services(id),
  target_url text not null, quantity integer not null check (quantity > 0), amount_kobo bigint not null check (amount_kobo > 0),
  status text not null default 'awaiting_payment' check (status in ('awaiting_payment','paid','queued','processing','completed','partial','failed','refunded')),
  idempotency_key uuid not null, provider_order_id text, created_at timestamptz not null default now(), unique (user_id, idempotency_key));
create table public.smg_payments (
  id uuid primary key default gen_random_uuid(), order_id uuid not null references public.smg_orders(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade,
  paystack_reference text not null unique, amount_kobo bigint not null check (amount_kobo > 0), currency text not null default 'NGN',
  status text not null default 'initialized' check (status in ('initialized','success','failed')), created_at timestamptz not null default now(), verified_at timestamptz);
alter table public.smg_services enable row level security; alter table public.smg_orders enable row level security; alter table public.smg_payments enable row level security;
create policy smg_services_public_read on public.smg_services for select using (is_active = true and provider_verified = true);
create policy smg_orders_owner_read on public.smg_orders for select using (auth.uid() = user_id);
create policy smg_payments_owner_read on public.smg_payments for select using (auth.uid() = user_id);
